import os,sys,json,base64,zlib,subprocess,hashlib,requests
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir(exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
revision='5a58d02802e399967637453f76c56bed232a9918'
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code)
sys.path[:0]=[str(code/'src'),str(code)]
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
(out/'runner_provenance.json').write_text(json.dumps(dict(seed=20261013,git_commit=revision,runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='validation19 integration only; no independent release or sealed data'),indent=2))
subprocess.run([sys.executable,'-m','pip','install','pytest','pyarrow','statsmodels'],check=True)
excluded=['tests/test_comp3.py','tests/test_letter_head.py','tests/test_bank_report.py','tests/test_kaggle_kill_test_run.py']
(out/'cloud_test_scope.json').write_text(json.dumps(dict(excluded=excluded,source_commit=revision,scope='full current portable suite with same four historical exclusions'),indent=2))
result=subprocess.run([sys.executable,'-m','pytest','-q','tests']+['--ignore='+p for p in excluded],cwd=code,capture_output=True,text=True)
(out/'pytest.txt').write_text(result.stdout+result.stderr);print(result.stdout,flush=True)
assert result.returncode==0,'portable tests failed before EEG access'
root=Path('/kaggle/input')
def unique(name):
    matches=list(root.rglob(name));assert len(matches)==1,(name,len(matches))
    return matches[0]
schedule=unique('schedule.mat');raw=Path('/kaggle/working/sess01_subj19_EEG_ERP.mat')
url='https://s3.ap-northeast-1.wasabisys.com/gigadb-datasets/live/pub/10.5524/100001_101000/100542/session1/s19/'+raw.name
with requests.get(url,stream=True,timeout=(30,300)) as response:
    response.raise_for_status()
    with raw.open('wb') as handle:
        for chunk in response.iter_content(1024*1024):handle.write(chunk)
digest=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
from p3a.data.openbmi_manifest import build_subject_manifest
protocol=json.loads((code/'configs/openbmi_independent_protocol_candidate.json').read_text())
protocol['status']='validation_integration_only'
work=Path('/kaggle/working/validation_bindings');work.mkdir()
pp=work/'protocol.json';mp=work/'manifest.json';rp=work/'receipt.json'
pp.write_text(json.dumps(protocol,indent=2))
train=[f'openbmi_candidate:s19_session1:train:{i:03d}' for i in range(33)]
test=[f'openbmi_candidate:s19_session1:test:{i:03d}' for i in range(36)]
mp.write_text(json.dumps(build_subject_manifest(19,train,test,digest(raw),digest(pp)),indent=2))
rp.write_text(json.dumps(dict(status='validation_integration_only',protocol_sha256=digest(pp),manifest_sha256=digest(mp)),indent=2))
common=['--protocol',str(pp),'--manifest',str(mp),'--release-receipt',str(rp),'--validation-integration','--subject','19','--raw-file',str(raw),'--schedule',str(schedule),'--git-commit',revision]
for seed in [20261013,20261014,20261015]:
    folder=out/f'seed{seed}';folder.mkdir(exist_ok=True)
    command=[sys.executable,str(code/'scripts/run_openbmi_independent_subject.py')]+common+['--seed',str(seed),'--checkpoint',str(unique(f'source_seed{seed}.pt')),'--references',str(unique(f'references_seed{seed}.npz')),'--reference-json',str(unique(f'references_seed{seed}.json')),'--template',str(unique(f'source_template_seed{seed}.pt')),'--out-dir',str(folder)]
    # common contains no out-dir; exact input/code-bound stage ledger skips completed work.
    subprocess.run(command,check=True)
    receipt=folder/'subject_execution.json';before=digest(receipt)
    subprocess.run(command,check=True)
    assert digest(receipt)==before,'completed subject ledger changed on resume'
    (out/f'subject_integration_seed{seed}.json').write_text(json.dumps(dict(seed=seed,subject=19,scope='all36-character validation-only execution; not sealed outcomes',resume_content_unchanged=True,receipt_sha256=before),indent=2))
subprocess.run([sys.executable,str(code/'scripts/aggregate_openbmi_reliability.py'),'--root',str(out),'--protocol',str(pp),'--out-dir',str(out/'aggregate'),'--git-commit',revision,'--seed','20261013','--validation-integration'],check=True)
raw.unlink()
(out/'subject_integration_complete.json').write_text(json.dumps(dict(source_commit=revision,seeds=[20261013,20261014,20261015],subject=19,scope='full controller+aggregation validation; no independent unlock'),indent=2))
